  c += vec3(0.79, 0.64, 0.36) * 0.11 * exp(-pow((y - hz) * 9.0, 2.0));
  c += vec3(0.18, 0.24, 0.48) * 0.12 * exp(-pow((y - hz - 0.08) * 4.0, 2.0));
  c *= mix(0.55, 1.0, smoothstep(0.0, hz, y));
